code:
import oge

oge.initialize()
service = oge.Service.initialize()

study_geom = service.getProcess("Geometry.Polygon").execute(
    [[[114.24, 30.52], [114.24, 30.58], [114.34, 30.58],
      [114.34, 30.52], [114.24, 30.52]]],
    "EPSG:4326"
)
study_feature = service.getProcess("Feature.loadFromGeometry").execute(
    study_geom, {"name": "study_area"}
)
study_fc = service.getProcess("FeatureCollection.loadFromFeatureList").execute(
    [study_feature]
)

skeleton_geom = service.getProcess("Geometry.LineString").execute(
    [[114.245, 30.545], [114.29, 30.552], [114.335, 30.558]],
    "EPSG:4326"
)
skeleton_feature = service.getProcess("Feature.loadFromGeometry").execute(
    skeleton_geom, {"name": "support_skeleton"}
)
support_buffer = service.getProcess("Feature.buffer").execute(
    skeleton_feature, 800, "EPSG:4326"
)
support_fc = service.getProcess("FeatureCollection.loadFromFeatureList").execute(
    [support_buffer]
)

reserve_geom = service.getProcess("Geometry.Polygon").execute(
    [[[114.255, 30.538], [114.255, 30.572], [114.325, 30.572],
      [114.325, 30.538], [114.255, 30.538]]],
    "EPSG:4326"
)
reserve_feature = service.getProcess("Feature.loadFromGeometry").execute(
    reserve_geom, {"name": "reserve_zone"}
)
reserve_fc = service.getProcess("FeatureCollection.loadFromFeatureList").execute(
    [reserve_feature]
)

key_node_geom = service.getProcess("Geometry.Point").execute(
    [114.2885828, 30.5512112],
    "EPSG:4326"
)
key_node_feature = service.getProcess("Feature.loadFromGeometry").execute(
    key_node_geom,
    {"name": "中华路1号码头", "fclass": "ferry_terminal"}
)
exclusion_buffer = service.getProcess("Feature.buffer").execute(
    key_node_feature, 300, "EPSG:4326"
)
exclusion_fc = service.getProcess("FeatureCollection.loadFromFeatureList").execute(
    [exclusion_buffer]
)

priority_base = service.getProcess(
    "FeatureCollection.intersection"
).execute(support_fc, reserve_fc)

priority_zone = service.getProcess(
    "FeatureCollection.difference"
).execute(priority_base, exclusion_fc, "geom", "geom")

restricted_tmp = service.getProcess(
    "FeatureCollection.difference"
).execute(study_fc, priority_zone, "geom", "geom")

restricted_zone = service.getProcess(
    "FeatureCollection.difference"
).execute(restricted_tmp, exclusion_fc, "geom", "geom")

restricted_zone.styles(["#CCCCCC"]).getMap("限制区")
support_fc.styles(["#FFCC00"]).getMap("主支撑约束结果")
reserve_fc.styles(["#99CCFF"]).getMap("附加保留约束结果")
priority_zone.styles(["#66CC66"]).getMap("优先区")
exclusion_fc.styles(["#CC3333"]).getMap("排除区")

oge.mapclient.centerMap(114.2886, 30.5512, 14)

import oge

oge.initialize()
service = oge.Service.initialize()

# 构造一条较短但速度较低的道路
road1_geom = service.getProcess("Geometry.LineString").execute(
    [[114.30, 30.55], [114.34, 30.55]], "EPSG:4326"
)
road1 = service.getProcess("Feature.loadFromGeometry").execute(
    road1_geom, {"name": "short_slow_road", "speed": 20}
)

# 构造一条距离较长但速度较高的绕行道路
road2_geom = service.getProcess("Geometry.LineString").execute(
    [[114.30, 30.55], [114.30, 30.56]], "EPSG:4326"
)
road2 = service.getProcess("Feature.loadFromGeometry").execute(
    road2_geom, {"name": "fast_road_1", "speed": 80}
)

road3_geom = service.getProcess("Geometry.LineString").execute(
    [[114.30, 30.56], [114.34, 30.56]], "EPSG:4326"
)
road3 = service.getProcess("Feature.loadFromGeometry").execute(
    road3_geom, {"name": "fast_road_2", "speed": 80}
)

road4_geom = service.getProcess("Geometry.LineString").execute(
    [[114.34, 30.56], [114.34, 30.55]], "EPSG:4326"
)
road4 = service.getProcess("Feature.loadFromGeometry").execute(
    road4_geom, {"name": "fast_road_3", "speed": 80}
)

streets = service.getProcess(
    "FeatureCollection.loadFromFeatureList"
).execute([road1, road2, road3, road4])

start_text = "114.30,30.55 [EPSG:4326]"
end_text = "114.34,30.55 [EPSG:4326]"

start_geom = service.getProcess("Geometry.Point").execute(
    [114.30, 30.55], "EPSG:4326"
)
end_geom = service.getProcess("Geometry.Point").execute(
    [114.34, 30.55], "EPSG:4326"
)

start = service.getProcess("Feature.loadFromGeometry").execute(
    start_geom, {"name": "start"}
)
end = service.getProcess("Feature.loadFromGeometry").execute(
    end_geom, {"name": "end"}
)

path_process = service.getProcess(
    "FeatureCollection.shortestPathPointToPointByQGIS"
)

# 最短距离路径
shortest_path = path_process.execute(
    streets, "", "", start_text, "2", "0",
    0.0, 50.0, "", end_text, "", ""
)

# 使用统一默认速度的最快路径
fastest_default = path_process.execute(
    streets, "", "", start_text, "2", "1",
    0.0, 50.0, "", end_text, "", ""
)

# 使用speed字段计算最快路径
fastest_speed = path_process.execute(
    streets, "", "", start_text, "2", "1",
    0.0, 50.0, "", end_text, "", "speed"
)

streets.styles(["#BDBDBD"]).getMap("简化道路网络")
shortest_path.styles(["#FFCC33"]).getMap("最短距离路径")
fastest_default.styles(["#FF66CC"]).getMap("默认速度最快路径")
fastest_speed.styles(["#33CC66"]).getMap("考虑限速的最快路径")
start.styles(["#0000FF"]).getMap("起点")
end.styles(["#FF0000"]).getMap("终点")

oge.mapclient.centerMap(114.32, 30.555, 14)
